-- Run in a NEW Supabase project SQL Editor. Each staff account owns its own data.
create extension if not exists pgcrypto;
create table if not exists public.exhibitions(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,edition_year int not null check(edition_year between 2000 and 2100),directory_url text,directory_total int check(directory_total>=0),created_at timestamptz not null default now(),unique(owner_id,name,edition_year));
create table if not exists public.exhibitors(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),exhibition_id uuid not null references public.exhibitions(id) on delete cascade,company_name text not null,country text,description text,website text,email text,phone text,hall text,stand text,profile_url text,contact_source_url text,date_checked date,verification_status text not null default 'pending' check(verification_status in ('pending','verified','directory_only','conflict','not_found')),participation_status text not null default 'directory_listing' check(participation_status in ('directory_listing','historical','confirmed_current')),notes text,created_at timestamptz not null default now());
create unique index if not exists exhibitor_profile_unique on public.exhibitors(exhibition_id,profile_url) where profile_url is not null;
create table if not exists public.research_runs(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),exhibition_id uuid not null references public.exhibitions(id) on delete cascade,status text not null default 'queued' check(status in ('queued','running','paused','completed','failed')),cursor text,pages_processed int not null default 0,profiles_processed int not null default 0,duplicates_removed int not null default 0,gaps jsonb not null default '[]'::jsonb,started_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.research_sources(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),exhibitor_id uuid not null references public.exhibitors(id) on delete cascade,source_url text not null,source_type text not null,field_name text,checked_at timestamptz not null default now(),notes text);
create table if not exists public.outreach_log(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),exhibitor_id uuid not null references public.exhibitors(id) on delete cascade,campaign_key text not null,status text not null default 'draft',sent_at timestamptz,reply_at timestamptz,created_at timestamptz not null default now(),unique(owner_id,exhibitor_id,campaign_key));
create index if not exists exhibitors_event_idx on public.exhibitors(exhibition_id);
create index if not exists research_runs_event_idx on public.research_runs(exhibition_id);
-- Enforce that child rows can only reference a parent belonging to the same owner.
create unique index if not exists exhibitions_owner_id_idx on public.exhibitions(owner_id,id);
create unique index if not exists exhibitors_owner_id_idx on public.exhibitors(owner_id,id);
alter table public.exhibitors add constraint exhibitors_owned_event foreign key(owner_id,exhibition_id) references public.exhibitions(owner_id,id);
alter table public.research_runs add constraint runs_owned_event foreign key(owner_id,exhibition_id) references public.exhibitions(owner_id,id);
alter table public.research_sources add constraint sources_owned_exhibitor foreign key(owner_id,exhibitor_id) references public.exhibitors(owner_id,id);
alter table public.outreach_log add constraint outreach_owned_exhibitor foreign key(owner_id,exhibitor_id) references public.exhibitors(owner_id,id);
alter table public.exhibitions enable row level security;
alter table public.exhibitors enable row level security;
alter table public.research_runs enable row level security;
alter table public.research_sources enable row level security;
alter table public.outreach_log enable row level security;
do $$ declare t text; begin foreach t in array array['exhibitions','exhibitors','research_runs','research_sources','outreach_log'] loop execute format('create policy "own_select" on public.%I for select to authenticated using ((select auth.uid())=owner_id)',t);execute format('create policy "own_insert" on public.%I for insert to authenticated with check ((select auth.uid())=owner_id)',t);execute format('create policy "own_update" on public.%I for update to authenticated using ((select auth.uid())=owner_id) with check ((select auth.uid())=owner_id)',t);execute format('create policy "own_delete" on public.%I for delete to authenticated using ((select auth.uid())=owner_id)',t);end loop;end $$;
